 cpu=time.process_time();wall=time.perf_counter();G=Path(__file__).resolve().parents[1];D=Path('/workspace/haic-response547-private');read=lambda p:json.loads(p.read_text());sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest();c=read(G/'retry/filter547_contract.json');r=read(G/'retry/filter547_pilot_result.json');assert all(sha(G/p)==h for p,h in c['source_sha256'].items()) and all(sha(Path(p))==h for p,h in c['private_inputs_sha256'].items());assert not r['passed'] and not r['learning_gate'] and not r['promotion_eligible'];assert r['accepted_feasible_updates']==0 and r['rejection_counts']==dict(exact_constraint=4,model_reliability=0,objective=0,numerical=0);assert len(r['local_models'])==1 and len(r['local_models'][0]['trials'])==4
