 rounding=dict(constraint='terminal_path_error',stored_center_slack=float(g0[1024]),risk_band=float(bands[1024]),positive_float_difference=float(g0[1024]-bands[1024]),difference_in_band_ULPs=float((g0[1024]-bands[1024])/np.spacing(bands[1024])),center_risk_flag=bool(g0[1024]<=bands[1024]),fraction_reserve_applied_m=float(np.where(g0<=bands,.25*np.maximum(g0,0),0)[1024]),mathematically_equal_boundary_should_be_treated_conservatively=True,no_rule_changed_or_rerun=True);assert not rounding['center_risk_flag'] and rounding['fraction_reserve_applied_m']==0 and rounding['difference_in_band_ULPs']==6
